#!/usr/bin/env python3
"""STATE-Bench portable domain skill CLI.

Commands:
  tools                                      Print the domain tool schemas (OpenAI function format).
  call  <tool> --args '<json>' [--now <iso>]  Run a tool against the unified world.db (reads/mutates it).
  reset                                      Clear this skill's multi-step session gates (no-op on data).

State model: domain data lives in the unified per-task `world.db` (seeded fresh
into /workspace by the runner). `ENV_DATA_CLASS.load()` reads this skill's scoped
slice from world.db and `.save()` writes mutations straight back — there is no
db.json seed and no state.json working copy. Multi-step gates (policy-check ->
preview -> confirm) still persist in a local `session.json` under the workspace
(fresh per task since skills upload clean into each sandbox). `reset` clears those
gates; the data itself is re-seeded per task by the runner. By default the session
file lives in `<skill>/.state/`; override with --workspace.
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

from domain_meta import DEFAULT_NOW, DEFAULT_USER, ENV_CLASS, ENV_DATA_CLASS, SAVE_MAP  # noqa: E402
from tools import TOOL_SCHEMAS, WRITE_TOOL_NAMES  # noqa: E402


# --- session-state (sets/tuples) JSON codec -------------------------------
def _enc(o):
    if isinstance(o, set):
        return {"__set__": [_enc(x) for x in o]}
    if isinstance(o, tuple):
        return {"__tuple__": [_enc(x) for x in o]}
    if isinstance(o, dict):
        return {k: _enc(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_enc(x) for x in o]
    return o


def _dec(o):
    if isinstance(o, dict):
        if set(o.keys()) == {"__set__"}:
            return {_dec(x) for x in o["__set__"]}
        if set(o.keys()) == {"__tuple__"}:
            return tuple(_dec(x) for x in o["__tuple__"])
        return {k: _dec(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_dec(x) for x in o]
    return o


def _emit(obj, code=0):
    print(json.dumps(obj, ensure_ascii=False, indent=2))
    sys.exit(code)


def _workspace(args) -> Path:
    return Path(args.workspace) if getattr(args, "workspace", None) else (HERE / ".state")


def _seed_if_needed(ws: Path) -> Path:
    """Ensure the workspace dir exists and return the (session-only) state path.

    Domain data now lives in world.db (see schemas.py), so there is no db.json to
    copy; this just guarantees the workspace dir for session.json.
    """
    ws.mkdir(parents=True, exist_ok=True)
    return ws / "state.json"


def cmd_tools(_args):
    _emit({"write_tools": WRITE_TOOL_NAMES, "default_user": DEFAULT_USER, "now": DEFAULT_NOW, "tools": TOOL_SCHEMAS})


def cmd_reset(args):
    ws = _workspace(args)
    for name in ("state.json", "session.json"):
        p = ws / name
        if p.exists():
            p.unlink()
    _emit({"ok": True, "reset": True, "workspace": str(ws),
           "note": "session gates cleared; domain data is re-seeded per task from world.db"})


def cmd_call(args):
    ws = _workspace(args)
    state_path = _seed_if_needed(ws)
    now = args.now or DEFAULT_NOW
    try:
        params = json.loads(args.args) if args.args else {}
    except json.JSONDecodeError as e:
        _emit({"error": f"--args must be valid JSON: {e}"}, 1)
    if not isinstance(params, dict):
        _emit({"error": "--args must be a JSON object"}, 1)

    env_data = ENV_DATA_CLASS.load(state_path)
    env = ENV_CLASS(env_data, now=now)

    session_path = ws / "session.json"
    if session_path.exists():
        for k, v in _dec(json.loads(session_path.read_text())).items():
            setattr(env, k, v)

    handler = env.tool_handlers.get(args.tool)
    if handler is None:
        _emit({"error": f"Unknown tool '{args.tool}'. Run `tools` to list available tools."}, 1)

    try:
        result = handler(params)
    except Exception as e:  # domain handlers raise on bad input; surface as JSON
        _emit({"error": f"{type(e).__name__}: {e}"}, 1)

    # Persist mutated DB (rebuild EnvironmentData from live indexes so created rows are captured).
    rebuilt = ENV_DATA_CLASS(**{field: list(getattr(env, attr).values()) for field, attr in SAVE_MAP.items()})
    rebuilt.save(state_path)

    # Persist multi-step session flags (policy-check / preview gates).
    sess_out = {k: v for k, v in vars(env).items() if k.startswith("_")}
    session_path.write_text(json.dumps(_enc(sess_out), indent=2))

    is_write = args.tool in WRITE_TOOL_NAMES
    _emit({"tool": args.tool, "is_write": is_write, "result": result})


def main():
    p = argparse.ArgumentParser(description="STATE-Bench portable domain skill CLI")
    sub = p.add_subparsers(dest="cmd", required=True)
    sub.add_parser("tools").set_defaults(fn=cmd_tools)
    pr = sub.add_parser("reset")
    pr.add_argument("--workspace", default=None)
    pr.set_defaults(fn=cmd_reset)
    pc = sub.add_parser("call")
    pc.add_argument("tool")
    pc.add_argument("--args", default="{}")
    pc.add_argument("--now", default=None)
    pc.add_argument("--workspace", default=None)
    pc.set_defaults(fn=cmd_call)
    a = p.parse_args()
    a.fn(a)


if __name__ == "__main__":
    main()

def create_booking(self, params: dict[str, Any]) -> dict[str, Any]:
    """Create a new booking with explicit persisted booking preferences.

    Required persisted booking fields: meal_preference, cabin_class, seat_type,
    add_wifi, add_extra_legroom, and add_insurance. Runtime never infers these
    from the user profile.
    """
    flight_id = params.get("flight_id", "")
    flight = self.flights.get(flight_id)
    if not flight:
        return {"error": f"Flight {flight_id} not found."}
    if flight.status == "cancelled":
        return {"error": f"Flight {flight_id} is cancelled and cannot be booked."}

    user_id = params.get("user_id", "unknown")
    user = self.users.get(user_id)

    # Require cabin_class
    cabin_class = params.get("cabin_class")
    if not cabin_class:
        return {"error": f"cabin_class is required. Available cabins for this flight: {_available_cabins(flight)}."}
    if cabin_class not in flight.cabin_prices:
        return self._cabin_unavailable_error(cabin_class, flight_id, flight)

    cabin_price = flight.cabin_prices[cabin_class]

    # Require seat_type
    seat_type = params.get("seat_type")
    if not seat_type:
        return {"error": "seat_type is required. Must be one of: window, middle, aisle."}
    if seat_type not in ("window", "middle", "aisle"):
        return {"error": f"Invalid seat_type '{seat_type}'. Must be one of: window, middle, aisle."}

    # Require payment_method
    payment_method = params.get("payment_method")
    if not payment_method:
        return {"error": "payment_method is required. Must be one of: credit_card, points, points_plus_cash."}
    if payment_method not in ("credit_card", "points", "points_plus_cash"):
        return {
            "error": f"Invalid payment_method '{payment_method}'. Must be one of: credit_card, points, points_plus_cash."
        }

    missing_pref_error = self._missing_booking_preference_error(params)
    if missing_pref_error is not None:
        return missing_pref_error

    meal_preference = params["meal_preference"]
    add_wifi = self.parse_bool(params["add_wifi"])
    add_extra_legroom = self.parse_bool(params["add_extra_legroom"])
    add_insurance = self.parse_bool(params["add_insurance"])

    # Payment method handling (already validated above)
    points_used = 0
    cash_amount = cabin_price

    if payment_method in ("points", "points_plus_cash"):
        if not user:
            return {"error": f"User {user_id} not found. Cannot process points payment."}

        redemption = policies.check_loyalty_point_redemption(
            loyalty_tier=user.loyalty_tier,
            loyalty_points=user.loyalty_points,
            flight_price=cabin_price,
            route_type=flight.route_type,
        )
        if not redemption["eligible"]:
            return {"error": f"Points redemption not eligible: {redemption['reason']}"}

        points_used = redemption["points_used"]
        cash_amount = int(redemption["remaining_cash_payment"])

        # Require points_used for any points payment
        provided_points = params.get("points_used")
        if provided_points is None:
            return {"error": "points_used is required for points payments."}
        try:
            provided_points = int(provided_points)
        except (ValueError, TypeError):
            return {"error": f"Invalid points_used: {provided_points}. Must be an integer."}
        if provided_points != points_used:
            return {"error": "Incorrect points_used value."}

        # Reject payment_method="points" if points don't fully cover the flight
        if payment_method == "points" and cash_amount > 0:
            return {"error": "Insufficient points for full payment."}

        # Require cash_amount for points_plus_cash
        if payment_method == "points_plus_cash":
            provided_cash = params.get("cash_amount")
            if provided_cash is None:
                return {"error": "cash_amount is required for points_plus_cash payments."}
            try:
                provided_cash = int(provided_cash)
            except (ValueError, TypeError):
                return {"error": f"Invalid cash_amount: {provided_cash}. Must be an integer (USD)."}
            if provided_cash != cash_amount:
                return {"error": "Incorrect cash_amount value."}

        user.loyalty_points -= points_used

    # Extra baggage handling
    num_extra_bags = params.get("paid_checked_bags", 0)
    baggage_fee = 0
    if num_extra_bags and isinstance(num_extra_bags, int) and num_extra_bags > 0:
        # Use domestic rate as default
        baggage_fee = num_extra_bags * 35

    # Generate booking ID (handle non-numeric suffixes like BK-PR01, BK-A06a)
    existing_nums = []
    for bid in self.bookings:
        if bid.startswith("BK-"):
            try:
                existing_nums.append(int(bid.split("-")[1]))
            except ValueError:
                pass
    next_num = max(existing_nums, default=0) + 1
    booking_id = f"BK-{next_num:04d}"

    booking = Booking(
        booking_id=booking_id,
        user_id=user_id,
        flight_id=flight_id,
        status="confirmed",
        seat_type=params.get("seat_type"),
        cabin_class=cabin_class,
        meal_preference=meal_preference,
        add_wifi=add_wifi,
        add_extra_legroom=add_extra_legroom,
        add_insurance=add_insurance,
        price_paid=cash_amount + baggage_fee,
        payment_method=payment_method,
        points_used=points_used,
        cash_amount=cash_amount,
        booked_at=self.now,
        paid_checked_bags=num_extra_bags if isinstance(num_extra_bags, int) else 0,
    )
    self.bookings[booking_id] = booking

    result: dict[str, Any] = {
        "status": "confirmed",
        "booking_id": booking_id,
        "flight_id": flight_id,
        "cabin_class": cabin_class,
        "price": cabin_price,
        "payment_method": payment_method,
    }
    if points_used > 0:
        result["points_used"] = points_used
        result["cash_charged"] = cash_amount
    if baggage_fee > 0:
        result["baggage_fee"] = baggage_fee
        result["extra_bags"] = num_extra_bags

    return result

